import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const TIMER_TYPES = {
  FOCUS: 'focus',
  SHORT_BREAK: 'shortBreak',
  LONG_BREAK: 'longBreak'
};

const TIMER_CONFIGS = {
  [TIMER_TYPES.FOCUS]: { minutes: 25, color: '#3B82F6' }, // blue
  [TIMER_TYPES.SHORT_BREAK]: { minutes: 5, color: '#10B981' }, // green
  [TIMER_TYPES.LONG_BREAK]: { minutes: 15, color: '#8B5CF6' } // purple
};

const CircleTimer = ({ seconds, totalSeconds, color, size = 260, strokeWidth = 12 }) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const progressOffset = (seconds / totalSeconds) * circumference;
  
  return (
    <div className="relative" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="transform -rotate-90">
        {/* Background circle */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="#1F2937" // gray-800
          strokeWidth={strokeWidth}
          strokeOpacity="0.4"
        />
        
        {/* Progress circle */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          initial={{ strokeDasharray: circumference, strokeDashoffset: circumference }}
          animate={{ strokeDashoffset: circumference - progressOffset }}
          transition={{ duration: 0.5, ease: "linear" }}
          style={{
            strokeDasharray: circumference,
          }}
        />
      </svg>
    </div>
  );
};

const AnimatedPomodoroTimer = ({ tasks = [] }) => {
  const [currentTimer, setCurrentTimer] = useState(TIMER_TYPES.FOCUS);
  const [timeLeft, setTimeLeft] = useState(TIMER_CONFIGS[TIMER_TYPES.FOCUS].minutes * 60);
  const [totalTime, setTotalTime] = useState(TIMER_CONFIGS[TIMER_TYPES.FOCUS].minutes * 60);
  const [isRunning, setIsRunning] = useState(false);
  const [focusCount, setFocusCount] = useState(0);
  const [selectedTask, setSelectedTask] = useState(null);
  const [showTaskSelector, setShowTaskSelector] = useState(false);
  const timerRef = useRef(null);
  
  // Format time as MM:SS
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };
  
  // Reset timer when changing timer type
  useEffect(() => {
    const config = TIMER_CONFIGS[currentTimer];
    setTimeLeft(config.minutes * 60);
    setTotalTime(config.minutes * 60);
    setIsRunning(false);
    
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [currentTimer]);
  
  // Handle timer countdown
  useEffect(() => {
    if (isRunning && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            clearInterval(timerRef.current);
            handleTimerComplete();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    }
    
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [isRunning, timeLeft]);
  
  const handleTimerComplete = () => {
    setIsRunning(false);
    
    // Play sound
    const audio = new Audio('/timer-complete.mp3');
    audio.play().catch(e => console.error('Error playing audio:', e));
    
    // Show notification
    if (Notification.permission === 'granted') {
      new Notification('Timer Complete', {
        body: currentTimer === TIMER_TYPES.FOCUS 
          ? 'Time for a break!' 
          : 'Time to focus!',
      });
    }
    
    // Update pomodoro count and switch timer type
    if (currentTimer === TIMER_TYPES.FOCUS) {
      setFocusCount(prev => prev + 1);
      
      // After 4 pomodoros, take a long break
      if ((focusCount + 1) % 4 === 0) {
        setCurrentTimer(TIMER_TYPES.LONG_BREAK);
      } else {
        setCurrentTimer(TIMER_TYPES.SHORT_BREAK);
      }
    } else {
      setCurrentTimer(TIMER_TYPES.FOCUS);
    }
  };
  
  const toggleTimer = () => {
    setIsRunning(!isRunning);
  };
  
  const resetTimer = () => {
    setIsRunning(false);
    setTimeLeft(TIMER_CONFIGS[currentTimer].minutes * 60);
  };
  
  const skipTimer = () => {
    handleTimerComplete();
  };
  
  const handleTaskSelect = (task) => {
    setSelectedTask(task);
    setShowTaskSelector(false);
  };
  
  return (
    <div className="flex flex-col items-center w-full max-w-md mx-auto p-6 bg-gray-900 bg-opacity-40 backdrop-blur-lg rounded-2xl shadow-xl">
      <h2 className="text-2xl font-bold text-white mb-6">Pomodoro Timer</h2>
      
      {/* Timer Type Selector */}
      <div className="flex space-x-2 mb-8">
        {Object.entries(TIMER_TYPES).map(([key, value]) => (
          <motion.button
            key={key}
            className={`px-4 py-2 rounded-lg font-medium transition shadow-lg ${
              currentTimer === value
                ? 'bg-white text-gray-900'
                : 'bg-gray-800 text-gray-300 hover:bg-gray-700'
            }`}
            onClick={() => setCurrentTimer(value)}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            animate={{ 
              backgroundColor: currentTimer === value ? '#FFFFFF' : '#1F2937',
              color: currentTimer === value ? '#111827' : '#D1D5DB'
            }}
          >
            {key === 'FOCUS' 
              ? 'Focus' 
              : key === 'SHORT_BREAK' 
                ? 'Short Break' 
                : 'Long Break'}
          </motion.button>
        ))}
      </div>
      
      {/* Timer Circle */}
      <div className="relative flex justify-center items-center mb-8">
        <CircleTimer
          seconds={timeLeft}
          totalSeconds={totalTime}
          color={TIMER_CONFIGS[currentTimer].color}
        />
        
        <div className="absolute inset-0 flex flex-col items-center justify-center text-white">
          <motion.h3 
            className="text-5xl font-bold font-mono"
            key={timeLeft}
            initial={{ opacity: 0.5, scale: 0.9 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.2 }}
          >
            {formatTime(timeLeft)}
          </motion.h3>
          <p className="text-lg opacity-75 capitalize mt-2">{currentTimer.replace(/([A-Z])/g, ' $1').trim()}</p>
        </div>
      </div>
      
      {/* Controls */}
      <div className="flex space-x-4 mb-8">
        <motion.button
          className={`px-6 py-3 rounded-full font-semibold shadow-lg ${
            isRunning ? 'bg-red-500 hover:bg-red-600' : 'bg-blue-500 hover:bg-blue-600'
          } text-white`}
          onClick={toggleTimer}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {isRunning ? 'Pause' : 'Start'}
        </motion.button>
        
        <motion.button
          className="px-6 py-3 rounded-full font-semibold bg-gray-700 hover:bg-gray-600 text-white shadow-lg"
          onClick={resetTimer}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          disabled={isRunning}
        >
          Reset
        </motion.button>
        
        <motion.button
          className="px-6 py-3 rounded-full font-semibold bg-gray-700 hover:bg-gray-600 text-white shadow-lg"
          onClick={skipTimer}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          disabled={isRunning}
        >
          Skip
        </motion.button>
      </div>
      
      {/* Task Association */}
      <div className="w-full">
        <div className="flex justify-between items-center mb-3">
          <h3 className="text-lg font-medium text-white">Current Task:</h3>
          <motion.button
            className="text-sm px-3 py-1 rounded-full bg-blue-500 text-white"
            onClick={() => setShowTaskSelector(!showTaskSelector)}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            {showTaskSelector ? 'Cancel' : 'Change Task'}
          </motion.button>
        </div>
        
        {/* Selected Task or Placeholder */}
        <motion.div 
          className="p-4 bg-gray-800 rounded-lg mb-4 flex items-center"
          animate={{ 
            backgroundColor: selectedTask ? `rgba(${selectedTask.difficulty === 'hard' ? '239, 68, 68' : selectedTask.difficulty === 'medium' ? '245, 158, 11' : '16, 185, 129'}, 0.2)` : 'rgba(31, 41, 55, 0.6)' 
          }}
        >
          {selectedTask ? (
            <>
              <motion.div 
                className={`w-3 h-3 rounded-full mr-3 ${
                  selectedTask.difficulty === 'hard' 
                    ? 'bg-red-500' 
                    : selectedTask.difficulty === 'medium'
                      ? 'bg-amber-500'
                      : 'bg-green-500'
                }`}
                animate={{ 
                  boxShadow: selectedTask.difficulty === 'hard' 
                    ? '0 0 10px rgba(239, 68, 68, 0.7)'
                    : selectedTask.difficulty === 'medium' 
                      ? '0 0 8px rgba(245, 158, 11, 0.6)'
                      : '0 0 6px rgba(16, 185, 129, 0.5)'
                }}
                transition={{ duration: 1.5, repeat: Infinity, repeatType: 'reverse' }}
              />
              <div>
                <p className="text-white font-medium">{selectedTask.title}</p>
                <p className="text-gray-400 text-xs">{selectedTask.difficulty.toUpperCase()} · {formatTime(selectedTask.estimatedTime * 60)}</p>
              </div>
            </>
          ) : (
            <p className="text-gray-400">No task selected</p>
          )}
        </motion.div>
        
        {/* Task Selector */}
        <AnimatePresence>
          {showTaskSelector && (
            <motion.div
              className="mt-2 bg-gray-800 rounded-lg overflow-hidden shadow-xl"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
            >
              <div className="p-2 max-h-48 overflow-y-auto">
                {tasks.length > 0 ? (
                  tasks.map((task) => (
                    <motion.button
                      key={task.id}
                      className={`w-full p-3 text-left mb-1 rounded flex items-center ${
                        selectedTask?.id === task.id ? 'bg-blue-500 bg-opacity-20' : 'hover:bg-gray-700'
                      }`}
                      onClick={() => handleTaskSelect(task)}
                      whileHover={{ x: 4 }}
                    >
                      <div className={`w-2 h-2 rounded-full mr-3 ${
                        task.difficulty === 'hard' 
                          ? 'bg-red-500' 
                          : task.difficulty === 'medium'
                            ? 'bg-amber-500'
                            : 'bg-green-500'
                      }`} />
                      <div className="flex-grow">
                        <p className="text-white font-medium">{task.title}</p>
                        <p className="text-gray-400 text-xs">{task.difficulty.toUpperCase()} · {formatTime(task.estimatedTime * 60)}</p>
                      </div>
                    </motion.button>
                  ))
                ) : (
                  <p className="text-gray-400 p-3">No tasks available</p>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
      
      {/* Focus Sessions Counter */}
      <div className="mt-8 text-center">
        <p className="text-gray-400 mb-2">Focus Sessions Completed Today</p>
        <div className="flex justify-center space-x-2">
          {Array.from({ length: 8 }).map((_, i) => (
            <motion.div
              key={i}
              className={`w-4 h-4 rounded-full ${i < focusCount ? 'bg-blue-500' : 'bg-gray-700'}`}
              animate={{ 
                scale: i < focusCount ? [1, 1.2, 1] : 1,
                backgroundColor: i < focusCount ? '#3B82F6' : '#374151'
              }}
              transition={{ 
                scale: { duration: 0.3, delay: i * 0.1 },
                backgroundColor: { duration: 0.3 }
              }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default AnimatedPomodoroTimer;